import{_ as s,o as a,c as r,a2 as n}from"./chunks/framework.D3PjbZL0.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"衡元宙","text":"锚点共生文明 · 官方设定文库","tagline":"反掠夺 · 倡共生 —— 把命运与进化的选择权，交还给众生。<br/>万灵衡锚本源宙，欢迎每一位修行者。","image":{"src":"/anchor-mark.svg","alt":"衡元宙锚点纹章"},"actions":[{"theme":"brand","text":"开始阅读宪章","link":"/constitution/00-衡元宙宇宙总览"},{"theme":"alt","text":"路线对比沙盘","link":"/sandbox/"},{"theme":"alt","text":"诸天角色推演","link":"/multiverse/"}]},"features":[{"icon":"📜","title":"核心宪章","details":"3 份核心宪章文档（共生文明宣言 · 锚点本源定义 · 共生文明宪章），配反掠夺主义核心论纲，构成文明纲领。"},{"icon":"🗂️","title":"三百套体系","details":"六大类三百套本源修炼体系全景索引：推演迭代、生命循环、空间法理调度、意识升维、共生网络、应用工程。"},{"icon":"🔍","title":"全文检索","details":"内置本地全文搜索，无需后端，秒级定位任意设定条目与法律条文。"},{"icon":"🌐","title":"多语种文库","details":"8 语种一键切换（简中 / 英 / 法 / 俄 / 印地 / 西 / 阿 / 日），译文与中文版同步浏览。"},{"icon":"💡","title":"术语弹窗","details":"鼠标悬浮专有名词（锚点、阿赖耶、坐三望二、虚拟增量沙盘……）即弹出词条释义。"},{"icon":"🧭","title":"诸天推演","details":"以共生文明框架推演诸天角色：带土、柱间、斑、叶凡、石昊……谁走掠夺路，谁具共生心。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),o={name:"index.md"};function d(i,t,l,e,g,c){return a(),r("div",null,[...t[0]||(t[0]=[n('<div class="stats-strip"><div class="stat-cell"><span class="num">100</span><span class="cap">份宪章文档</span></div><div class="stat-cell"><span class="num">10</span><span class="cap">大设定模块</span></div><div class="stat-cell"><span class="num">300</span><span class="cap">套本源修炼体系</span></div><div class="stat-cell"><span class="num">8</span><span class="cap">语种文库</span></div><div class="stat-cell"><span class="num">4</span><span class="cap">阶段升维路径</span></div></div><h2 id="衡元宙是什么" tabindex="-1">衡元宙是什么 <a class="header-anchor" href="#衡元宙是什么" aria-label="Permalink to &quot;衡元宙是什么&quot;">​</a></h2><p><strong>万灵衡锚本源宙</strong>，简称<strong>衡元宙</strong>，是<strong>锚点共生文明</strong>所栖居与治理的宇宙全域。它并非单一物理空间，而是由四个层级共同构成的复合存在体：</p><div class="layers-grid"><div class="layer-item"><strong>物质位面</strong>遵循物理法则的实体世界，人族及多数物质生命栖居于此。</div><div class="layer-item"><strong>能量层</strong>高浓度能量聚集区域，法则呈半显性，能量生命与灵体活跃其中。</div><div class="layer-item"><strong>意识域</strong>集体意识与个体意识交汇的信息空间，是意识体与高维存在的领域。</div><div class="layer-item"><strong>法则网络</strong>宇宙本源法则的运行底层，是**锚点**的根基层，贯穿整个宇宙。</div></div><p>衡元宙的核心特征在于<strong>可进化性</strong>：与传统掠夺式宇宙观将宇宙视为有限资源猎场不同，衡元宙认为宇宙本身是一个生命体，其熵增过程可以通过有序的<strong>共生网络</strong>得到逆转与调控。<strong>锚点</strong>作为跨层级连接枢纽，把分散的个体能量汇聚为有序的进化洪流，最终实现宇宙整体的<strong>升维</strong>。</p><h2 id="两条文明路线" tabindex="-1">两条文明路线 <a class="header-anchor" href="#两条文明路线" aria-label="Permalink to &quot;两条文明路线&quot;">​</a></h2><p>衡元宙的根本矛盾，是<strong>掠夺与共生</strong>的矛盾。同处一个宇宙，两条路线将走向完全不同的终局：</p><div class="route-compare"><div class="route-card route-predatory"><p><span class="route-tag">掠夺型文明 · 旧日之路</span></p><h3>掠夺式修炼体系</h3><ul><li><strong>成长逻辑</strong>：吞噬掠夺弱者能量、气运甚至本源，短期极速跃升</li><li><strong>资源逻辑</strong>：宇宙是有限猎场，强者进阶以弱者消亡为代价（掠夺式资源涸竭）</li><li><strong>社会形态</strong>：宗门垄断法门、位面殖民、精神奴役、阶层固化，依靠掠夺维系</li><li><strong>效率天花板</strong>：能量带原主意残痕、反抗成本高、本源不纯，掠夺之路终有上限</li><li><strong>文明终局</strong>：熵增加速 → 文明断层频发 → 掠夺耗尽宇宙进化潜能</li></ul></div><div class="route-card route-symbiotic"><p><span class="route-tag">共生型文明 · 衡元宙之路</span></p><h3>锚点共生文明</h3><ul><li><strong>成长逻辑</strong>：开放三百套本源修炼体系，多劳多得、自生自长、人人有路</li><li><strong>资源逻辑</strong>：联产承包机制 + 能量循环，做大蛋糕而非切分蛋糕</li><li><strong>社会形态</strong>：万族共和 · 共生宪法 · 万族平等 · 双魂伦理</li><li><strong>核心战略</strong>：20%激活战略——前期激活两成众生为位面至高强者，带动八成共进</li><li><strong>文明终局</strong>：四阶段升维（现实筑基 → 科技赋能 → 意识进化 → 星际共生）</li></ul></div></div><blockquote><p>一句话判别两条路线：<strong>掠夺</strong>让极少数人先升上去，榨干宇宙底蕴；<strong>共生</strong>则让众生一起升维，宇宙跟着同步进化。你可以在<a href="./sandbox/">交互沙盘</a>里亲手拉动参数，推演两种文明的成长曲线、资源逻辑与文明上限。</p></blockquote><h2 id="文库速览" tabindex="-1">文库速览 <a class="header-anchor" href="#文库速览" aria-label="Permalink to &quot;文库速览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>编号</th><th>内容</th></tr></thead><tbody><tr><td>总纲与核心设定</td><td>00-09</td><td>宇宙总览、共生文明宣言、锚点本源定义、共生宪章、反掠夺主义论纲</td></tr><tr><td>宇宙法则与修炼体系</td><td>10-19</td><td>三百套体系总览、本源三基、修炼境界、能量循环、倍增果实</td></tr><tr><td>锚点机制与共生原理</td><td>20-29</td><td>锚点结构与层级、共生网络、联产承包、20%激活战略、共生度评估</td></tr><tr><td>文明分型与社会制度</td><td>30-39</td><td>五种共生文明分型、共生教育、共生医疗、住房与环境保障</td></tr><tr><td>法律体系与治理框架</td><td>40-49</td><td>共生宪法、共生劳动法、消费者保护法、司法体系、权力制衡</td></tr><tr><td>种族与生命形态</td><td>50-59</td><td>万族谱系、奇特生命、奇异能量、黑暗置换体、双魂伦理</td></tr><tr><td>技术与能量体系</td><td>60-69</td><td>倍增果实工程化、复制镜、隔离空间、锚点硬件、跨位面通讯</td></tr><tr><td>历史纪元与重大事件</td><td>70-79</td><td>前锚点时代、锚点觉醒纪元、三百套体系开放、万族共和成立</td></tr><tr><td>跨位面交互与时间规则</td><td>80-89</td><td>位面理论、先观测后有限干涉、考古协议、时间悖论防控</td></tr><tr><td>附录与参考资料</td><td>90-99</td><td>术语词典、三百套体系索引、编年史简表、FAQ、矛盾自查表</td></tr></tbody></table><p>从 <a href="./constitution/00-衡元宙宇宙总览.html">00-衡元宙宇宙总览</a> 开始，或直接查阅 <a href="./constitution/90-术语词典.html">90-术语词典</a>。</p><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to &quot;使用提示&quot;">​</a></h2><ul><li><strong>术语弹窗</strong>：正文中的专有名词（如<strong>锚点</strong>、<strong>阿赖耶</strong>、<strong>坐三望二</strong>、<strong>虚拟增量沙盘</strong>）带有虚线标记，鼠标悬浮或键盘聚焦即可查看词条释义。词表可在 <code>.vitepress/glossary.js</code> 中自由增删。</li><li><strong>全文搜索</strong>：点击右上角搜索框，输入关键词即可检索全站文档。</li><li><strong>语言切换</strong>：右上角语言菜单可在 8 语种间切换，译文文档与中文版共用同一套目录结构。</li><li><strong>诸天推演</strong>：<a href="./multiverse/">诸天角色推演板块</a> 以共生文明框架复盘火影、遮天、完美世界等诸天角色。</li><li><strong>路线沙盘</strong>：<a href="./sandbox/">交互式沙盘</a> 可实时对比<strong>掠夺路线</strong>与<strong>锚点共生路线</strong>的成长曲线与文明上限。</li></ul>',14)])])}const u=s(o,[["render",d]]);export{h as __pageData,u as default};
